export const workflowOverview=()=>`<section class="writing-overview-flow" aria-label="AI 写作流程"><div class="writing-overview-flow-head"><div><span class="capabilities-kicker">YOUR RESEARCH WORKFLOW</span><h2>写作流程 <small>（5 步完成高质量论文）</small></h2><p>每一步都可以保存和返回，先填写研究信息，再逐步完成写作。</p></div><a class="btn secondary" href="#help">查看写作指南</a></div><ol>${[['基础信息填写','填写论文题目、学段、专业与研究要求'],['精准知识补充','补充研究背景、方法和必要的知识材料'],['参考文献确认','核对并确认论文需要使用的参考文献'],['论文提纲确认','调整章节结构并确认论文写作提纲'],['生成版本确认','确认生成版本，检查格式并导出文档']].map(([title,desc],i)=>`<li class="${i===0?'active':''}"><span>${i+1}</span><div><b>${title}</b><small>${desc}</small></div></li>`).join('')}</ol></section>`;
export const workflowGuide=()=>`<section class="writing-process-guide" aria-label="毕业论文撰写流程"><div class="writing-process-head"><div><span class="capabilities-kicker">YOUR WRITING PROCESS</span><h2>按步骤完成毕业论文</h2><p>每一步都可以保存和返回，完成当前步骤后再进入下一步。</p></div><button type="button" class="btn secondary writing-process-toggle" aria-expanded="true">隐藏流程</button></div><ol>${[["基础信息填写","填写论文题目、学段、专业与研究要求"],["精准知识补充","补充研究背景、方法和必要的知识材料"],["参考文献确认","核对并确认论文需要使用的参考文献"],["论文提纲确认","调整章节结构并确认论文写作提纲"],["生成版本确认","确认生成版本，检查格式并导出文档"]].map(([title,desc],i)=>`<li data-writing-step="${i+1}"><span>${i+1}</span><div><b>${title}</b><small>${desc}</small></div></li>`).join("")}</ol><div class="writing-process-context"><span class="writing-process-context-icon" aria-hidden="true">i</span><p id="writing-process-context-text">当前步骤：请填写论文的基础信息。</p><button type="button" class="writing-process-next" id="writing-process-next">下一步：精准知识补充　→</button></div></section>`;
