$('[data-writing-step="5"]').addEventListener('click',showExport);
$('#writing-generate').addEventListener('click',()=>{if(!$('#writing-form').reportValidity())return;if(values().title.length<2){$('#writing-error').textContent='请填写至少 2 个字的题目或研究方向。';$('#writing-title').focus();return;}$('#writing-error').textContent='';workflowStage=2;render();$('#writing-material-review').scrollIntoView({block:'nearest'});});
