$('#outline-editor').addEventListener('input',()=>{$('#writing-status').textContent='大纲已修改，请完成编辑并保存。';});
$('#writing-form').addEventListener('submit',e=>{e.preventDefault();if(parsing)return;const v=values();if(v.title.length<2){$('#writing-error').textContent='请填写至少 2 个字的论文题目或研究方向。';$('#writing-title').focus();return;}$('#writing-error').textContent='';if(content&&!window.confirm('重新生成会替换当前大纲。已有章节正文会保留，确认后请核对章节关联。'))return;content=buildOutline(v);outlineConfirmed=false;workflowStage=3;editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';$('#preview-tag').textContent='本地模板';render();$('#writing-status').textContent='大纲模板已生成，可编辑、保存和导出。';});
$('#outline-edit').addEventListener('click',()=>{if(!content)return;outlineConfirmed=false;workflowStage=3;updateWorkflow();if(editing){sync();editing=false;render();}else{editing=true;$('#outline-editor').value=content;}$('#outline-editor').hidden=!editing;$('#outline-paper').hidden=editing;if(editing)$('#outline-editor').focus();$('#outline-edit').textContent=editing?'完成编辑':'✎　编辑大纲';});
$('#writing-save').addEventListener('click',()=>{if(parsing)return;if(!$('#writing-form').reportValidity())return;sync();const v=values();if(v.title.length<2){$('#writing-error').textContent='保存前请填写至少 2 个字的题目或研究方向。';return;}$('#writing-error').textContent='';material=$('#writing-material').value;const rows=read(),previous=rows.find(d=>String(d.id)===String(savedId)),now=new Date().toISOString(),hasBody=bodySections.some(s=>s.text.trim()),text=hasBody?composeBody(v,bodySections):content;const item={...previous,...v,id:savedId||crypto.randomUUID(),tool:taskKind==='writing'?'writing':taskKind,createdAt:previous?.createdAt||now,updatedAt:now,text,html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),outlineText:content,outlineConfirmed,bodySections,workflowStage,material,materialState,fileName,stage:hasBody?'body':content?'outline':'draft',date:new Date().toLocaleString('zh-CN')};const drafts=read(),i=drafts.findIndex(d=>String(d.id)===String(item.id));if(i>=0)drafts[i]=item;else drafts.unshift(item);try{localStorage.setItem('paperknow-drafts',JSON.stringify(drafts));savedId=item.id;markEditorSaved();$('#writing-status').textContent='已保存到当前浏览器，可在“我的成果”继续编辑。';$('#preview-tag').textContent=hasBody?'已保存正文':'已保存内容';try{recordTask({id:'draft-'+item.id,title:item.title,kind:hasBody?'本地正文保存':content?'本地大纲保存':'本地草稿保存',status:'completed',url:'#draft/'+item.id});}catch{$('#writing-status').textContent+=' 任务记录未保存。';}}catch{$('#writing-status').textContent='保存失败，浏览器空间可能不足，请先导出备份。';}});
$('#outline-export').addEventListener('click',()=>{sync();if(!content)return;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(values().title||'论文大纲').replace(/[\\/:*?"<>|]/g,'_')+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#outline-copy').hidden=false;$('#writing-status').textContent='已发起 TXT 下载。若浏览器未保存文件，可复制大纲全文。';});
$('#outline-copy').addEventListener('click',async()=>{sync();try{await navigator.clipboard.writeText(content);$('#writing-status').textContent='大纲已复制。';}catch{editing=true;$('#outline-editor').value=content;$('#outline-editor').hidden=false;$('#outline-paper').hidden=true;$('#outline-editor').focus();$('#outline-editor').select();$('#outline-edit').textContent='完成编辑';$('#writing-status').textContent='请使用系统复制快捷键复制已选中的大纲。';}});
async function parse(file){if(!file||parsing)return;const form=$('#writing-form');if(file.size>50*1024*1024){$('#material-status').textContent='请选择不超过 50MB 的文件。';return;}if(!/\.(docx|pdf|txt)$/i.test(file.name)){$('#material-status').textContent='仅支持 DOCX、PDF 或 UTF-8 TXT。';return;}parsing=true;$('#writing-material-confirm').disabled=true;$('#writing-save').disabled=true;$('#writing-generate').disabled=true;$('#material-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js'),r=await extractFile(file);if(!alive()||$('#writing-form')!==form){disposed=true;return;}if(!r.text.trim())throw new Error('未提取到正文；扫描 PDF 暂不支持，请转换为文本型文档。');if(r.text.length>20000)throw new Error('参考材料超过 20,000 字符，请选择较短的章节。');material=r.text;materialState='parsed';fileName=file.name;$('#writing-material').value=material;$('#material-toggle').hidden=false;renderMaterial();$('#material-status').textContent=`${fileName} · 已解析 ${material.length} 字符${r.warnings.length?' · '+r.warnings.slice(0,2).join('；'):''}`;}catch(err){if(alive()&&$('#writing-form')===form)$('#material-status').textContent=err.message||'解析失败，请检查文件。';}finally{parsing=false;if(alive()&&$('#writing-form')===form){$('#writing-material-confirm').disabled=false;$('#writing-save').disabled=false;$('#writing-generate').disabled=false;$('#writing-file').value='';}}}
$('#writing-file').addEventListener('change',e=>parse(e.target.files[0]));$('#writing-drop').addEventListener('dragover',e=>{e.preventDefault();$('#writing-drop').classList.add('dragover');});$('#writing-drop').addEventListener('dragleave',()=>$('#writing-drop').classList.remove('dragover'));$('#writing-drop').addEventListener('drop',e=>{e.preventDefault();$('#writing-drop').classList.remove('dragover');if(e.dataTransfer.files.length!==1){$('#material-status').textContent='请一次选择一份参考文档。';return;}parse(e.dataTransfer.files[0]);});$('#material-toggle').addEventListener('click',()=>{$('#material-area').hidden=!$('#material-area').hidden;});$('#material-remove').addEventListener('click',()=>{material='';fileName='';$('#writing-material').value='';$('#material-area').hidden=true;$('#material-toggle').hidden=true;$('#material-status').textContent='参考材料已移除，请保存以更新草稿。';renderMaterial();});if(material){$('#material-toggle').hidden=false;renderMaterial();$('#material-status').textContent=`${fileName||'参考材料'} · ${material.length} 字符`;}
